 void pin(float next,float fx,float fy){float old=Math.max(.01f,zoom);int hsvX=getScrollX(),svY=vertical.getScrollY();float contentX=(fx-shell.getLeft())/old,contentY=(fy+svY)/old;zoom=next;pages.setTranslationX(0);pages.setTranslationY(0);pages.setPivotX(0);pages.setPivotY(0);pages.setScaleX(zoom);pages.setScaleY(zoom);int w=Math.max(1,getWidth()),h=Math.max(1,getHeight());shell.forceLayout();shell.measure(MeasureSpec.makeMeasureSpec(w,MeasureSpec.EXACTLY),MeasureSpec.makeMeasureSpec(h,MeasureSpec.EXACTLY));int sheetW=shell.getMeasuredWidth(),sheetH=shell.getMeasuredHeight(),contentW=Math.max(w,sheetW);shell.getLayoutParams().width=sheetW;shell.getLayoutParams().height=sheetH;vertical.getLayoutParams().width=contentW;vertical.getLayoutParams().height=-1;vertical.forceLayout();vertical.measure(MeasureSpec.makeMeasureSpec(contentW,MeasureSpec.EXACTLY),MeasureSpec.makeMeasureSpec(h,MeasureSpec.EXACTLY));forceLayout();measure(MeasureSpec.makeMeasureSpec(w,MeasureSpec.EXACTLY),MeasureSpec.makeMeasureSpec(h,MeasureSpec.EXACTLY));layout(getLeft(),getTop(),getLeft()+w,getTop()+h);int left=zoom<1?Math.max(0,(contentW-sheetW)/2):0;shell.layout(left,0,left+sheetW,sheetH);pages.layout(0,0,pages.getMeasuredWidth(),pages.getMeasuredHeight());int x=Math.round(shell.getLeft()+contentX*zoom-fx+hsvX),y=Math.round(contentY*zoom-fy);if(zoom<=1.01f){int pan=Math.round(svY/old);if(pan!=0)pages.scrollBy(0,pan);y=0;}holdX=Math.max(0,Math.min(contentW-w,x));holdY=Math.max(0,Math.min(sheetH-h,y));applyHold();pages.setNestedScrollingEnabled(zoom<=1.01f);if(zoom>1.01f)pages.stopScroll();}
