 final class Shell extends FrameLayout{Shell(Context c){super(c);setClipChildren(false);setClipToPadding(false);}protected void onMeasure(int ws,int hs){int w=Math.max(1,PdfZoomHost.this.getWidth()>0?PdfZoomHost.this.getWidth():MeasureSpec.getSize(ws)),h=Math.max(1,MeasureSpec.getSize(hs));int contentH=zoom<1?Math.max(h,Math.round(h/zoom)):h;pages.measure(MeasureSpec.makeMeasureSpec(w,MeasureSpec.EXACTLY),MeasureSpec.makeMeasureSpec(contentH,MeasureSpec.EXACTLY));pages.setPivotX(0);pages.setPivotY(0);pages.setScaleX(zoom);pages.setScaleY(zoom);setMeasuredDimension(Math.max(1,Math.round(w*zoom)),Math.max(1,Math.round(contentH*zoom)));}protected void onLayout(boolean changed,int l,int t,int r,int b){pages.layout(0,0,pages.getMeasuredWidth(),pages.getMeasuredHeight());pages.setPivotX(0);pages.setPivotY(0);pages.setScaleX(zoom);pages.setScaleY(zoom);}}
 final class Vertical extends ScrollView {
 final ScaleGestureDetector detector;
 Vertical(Context c){super(c);setFillViewport(true);setClipChildren(false);setClipToPadding(false);detector=new ScaleGestureDetector(c,new ScaleGestureDetector.SimpleOnScaleGestureListener(){public boolean onScaleBegin(ScaleGestureDetector d){scaling=true;consume=true;cancelled=false;return true;}public boolean onScale(ScaleGestureDetector d){float factor=d.getScaleFactor();if(Float.isNaN(factor)||Math.abs(factor-1)<.002f)return true;float next=Math.max(.25f,Math.min(8,zoom*factor));if(Math.abs(next-zoom)>=.0005f)pin(next,d.getFocusX(),d.getFocusY());return true;}public void onScaleEnd(ScaleGestureDetector d){scaling=false;applyHold();post(()->{if(!scaling)holdX=holdY=null;});}});detector.setQuickScaleEnabled(false);}
 protected void onMeasure(int ws,int hs){int w=Math.max(1,PdfZoomHost.this.getWidth()>0?PdfZoomHost.this.getWidth():MeasureSpec.getSize(ws)),h=Math.max(1,MeasureSpec.getSize(hs));shell.measure(MeasureSpec.makeMeasureSpec(w,MeasureSpec.EXACTLY),MeasureSpec.makeMeasureSpec(h,MeasureSpec.EXACTLY));shell.getLayoutParams().width=shell.getMeasuredWidth();shell.getLayoutParams().height=shell.getMeasuredHeight();setMeasuredDimension(Math.max(w,shell.getMeasuredWidth()),h);}
 protected void onLayout(boolean changed,int l,int t,int r,int b){super.onLayout(changed,l,t,r,b);if(zoom<1){int left=Math.max(0,(getWidth()-shell.getMeasuredWidth())/2);shell.layout(left,0,left+shell.getMeasuredWidth(),shell.getMeasuredHeight());}applyHold();}
 public boolean dispatchTouchEvent(MotionEvent e){boolean pen=false;for(int i=0;i<e.getPointerCount();i++)if(e.getToolType(i)==MotionEvent.TOOL_TYPE_STYLUS||e.getToolType(i)==MotionEvent.TOOL_TYPE_ERASER)pen=true;if(!pen&&!scaling&&e.getPointerCount()==1&&(e.getActionMasked()==MotionEvent.ACTION_DOWN||e.getActionMasked()==MotionEvent.ACTION_MOVE))holdX=holdY=null;if(!pen&&e.getPointerCount()>=2){getParent().requestDisallowInterceptTouchEvent(true);requestDisallowInterceptTouchEvent(true);if(!cancelled){cancelled=true;MotionEvent cancel=MotionEvent.obtain(e);cancel.setAction(MotionEvent.ACTION_CANCEL);super.dispatchTouchEvent(cancel);cancel.recycle();}consume=true;}boolean handled=false;if(pen){if(scaling||consume){MotionEvent cancel=MotionEvent.obtain(e);cancel.setAction(MotionEvent.ACTION_CANCEL);detector.onTouchEvent(cancel);cancel.recycle();scaling=consume=cancelled=false;holdX=holdY=null;}}else handled=detector.onTouchEvent(e);if(consume&&!pen){getParent().requestDisallowInterceptTouchEvent(true);if(e.getActionMasked()==MotionEvent.ACTION_UP||e.getActionMasked()==MotionEvent.ACTION_CANCEL){scaling=consume=cancelled=false;applyHold();getParent().requestDisallowInterceptTouchEvent(false);post(()->{if(!scaling)holdX=holdY=null;});}return true;}return super.dispatchTouchEvent(e)||handled;}
 public boolean onInterceptTouchEvent(MotionEvent e){for(int i=0;i<e.getPointerCount();i++)if(e.getToolType(i)==MotionEvent.TOOL_TYPE_STYLUS||e.getToolType(i)==MotionEvent.TOOL_TYPE_ERASER)return false;if(zoom<=1.01f&&e.getPointerCount()<2)return false;return super.onInterceptTouchEvent(e);}
 }
